XP_APP=$(region $SG_H 'constexpr u64 kDownloadPlayTids[] = {' '};' | code_of | grep -o -E '0x[0-9A-Fa-f]{16}' | tr 'a-f' 'A-F' | sort -u | tr '\n' ' ')
